/bin/bash -lc "python3 - <<'PY'
import cv2,numpy as np
from PIL import Image
im=cv2.imread('first_frame.png'); hsv=cv2.cvtColor(im,cv2.COLOR_BGR2HSV)
for name,lo,hi in [('green',(25,60,60),(50,255,255)),('dark',(0,0,0),(180,255,45)),('low',(0,0,0),(180,255,80)),('gray',(0,0,80),(180,70,200))]:
 m=cv2.inRange(hsv,np.array(lo),np.array(hi)); n,l,st,cen=cv2.connectedComponentsWithStats(m)
 print('\\n',name,'count',m.sum()/255)
 for i in np.argsort(st[1:,4])[-15:][::-1]+1:
  x,y,w,h,a=st[i];
  if a>5: print((x,y,w,h,a),cen[i])
# dominant exact-ish clusters kmeans
pix=im.reshape(-1,3).astype(np.float32)
crit=(cv2.TERM_CRITERIA_EPS+cv2.TERM_CRITERIA_MAX_ITER,30,.2)
_,lab,cent=cv2.kmeans(pix,12,None,crit,5,cv2.KMEANS_PP_CENTERS)
for i,c in sorted(enumerate(cent),key=lambda z:-(lab==z[0]).sum()): print((lab==i).sum(),c[::-1].astype(int))
PY"
